<template><div class="page"><v-card flat class="hero pa-5 mb-4"><div class="d-flex align-center"><div><div class="text-overline">ORGANIZATION</div><h1 class="text-h5 font-weight-bold">Branches</h1><div class="grey--text">View offices, assigned users and projects.</div></div><v-spacer/><v-btn v-if="$can('settings.edit')" color="#165134" dark class="mr-2" @click="openCreate"><v-icon left>mdi-plus</v-icon>Add Branch</v-btn><v-btn icon @click="load"><v-icon>mdi-refresh</v-icon></v-btn></div></v-card><v-card flat outlined class="mb-4"><v-card-text><v-row dense><v-col cols="12" md="8"><v-text-field v-model="search" outlined dense clearable label="Search branch name or code" prepend-inner-icon="mdi-magnify" @keyup.enter="load" @click:clear="load"/></v-col><v-col cols="12" md="4"><v-select v-model="active" :items="activeOptions" item-text="text" item-value="value" outlined dense clearable label="Status" @change="load"/></v-col></v-row></v-card-text></v-card><v-card flat outlined><v-data-table :headers="headers" :items="items" :options.sync="options" :server-items-length="total"><template v-slot:item.is_head_office="{item}"><v-chip v-if="item.is_head_office" x-small color="primary" dark>Head Office</v-chip><span v-else>—</span></template><template v-slot:item.is_active="{item}"><v-chip x-small :color="item.is_active?'success':'grey'" dark>{{item.is_active?'Active':'Inactive'}}</v-chip></template><template v-slot:item.actions="{item}"><v-btn icon small @click="view(item)"><v-icon small>mdi-eye</v-icon></v-btn><v-btn v-if="$can('settings.edit')" icon small @click="edit(item)"><v-icon small>mdi-pencil</v-icon></v-btn><v-btn v-if="$can('settings.edit')" icon small color="error" @click="openDelete(item)"><v-icon small>mdi-delete-outline</v-icon></v-btn></template></v-data-table></v-card><v-dialog v-model="dialog" max-width="760"><v-card v-if="selected"><v-card-title>{{selected.name}}<v-spacer/><v-btn icon @click="dialog=false"><v-icon>mdi-close</v-icon></v-btn></v-card-title><v-card-text><v-row><v-col cols="12" md="6"><strong>Code:</strong> {{selected.code||'—'}}</v-col><v-col cols="12" md="6"><strong>Manager:</strong> {{selected.manager_name||'—'}}</v-col><v-col cols="12" md="6"><strong>Phone:</strong> {{selected.phone||'—'}}</v-col><v-col cols="12" md="6"><strong>Email:</strong> {{selected.email||'—'}}</v-col><v-col cols="12"><strong>Address:</strong> {{selected.address||selected.city||'—'}}</v-col></v-row><v-divider class="my-4"/><div class="subtitle-1 font-weight-bold mb-2">Active Users ({{(selected.users||[]).length}})</div><v-chip v-for="u in selected.users||[]" :key="u.id" small class="mr-2 mb-2">{{u.name}}</v-chip><div class="subtitle-1 font-weight-bold mt-3 mb-2">Projects ({{(selected.projects||[]).length}})</div><v-chip v-for="p in selected.projects||[]" :key="p.id" small outlined class="mr-2 mb-2">{{p.name}}</v-chip></v-card-text></v-card></v-dialog><v-dialog v-model="formDialog" max-width="760" persistent><v-card><v-card-title>{{editing?'Edit Branch':'Add Branch'}}<v-spacer/><v-btn icon :disabled="saving" @click="formDialog=false"><v-icon>mdi-close</v-icon></v-btn></v-card-title><v-card-text><v-row><v-col cols="12" md="6"><v-text-field v-model="form.name" outlined dense label="Branch Name *"/></v-col><v-col cols="12" md="6"><v-text-field v-model="form.code" outlined dense label="Branch Code *"/></v-col><v-col cols="12" md="6"><v-text-field v-model="form.manager_name" outlined dense label="Manager Name"/></v-col><v-col cols="12" md="6"><v-text-field v-model="form.phone" outlined dense label="Phone"/></v-col><v-col cols="12" md="6"><v-text-field v-model="form.email" outlined dense label="Email"/></v-col><v-col cols="12" md="6"><v-text-field v-model="form.city" outlined dense label="City"/></v-col><v-col cols="12" md="6"><v-text-field v-model="form.province" outlined dense label="Province"/></v-col><v-col cols="12"><v-textarea v-model="form.address" outlined dense rows="2" label="Address"/></v-col><v-col cols="12" md="6"><v-text-field v-model="form.latitude" type="number" outlined dense label="Latitude"/></v-col><v-col cols="12" md="6"><v-text-field v-model="form.longitude" type="number" outlined dense label="Longitude"/></v-col><v-col cols="12" md="6"><v-switch v-model="form.is_head_office" color="#165134" label="Head Office"/><div v-if="form.is_head_office" class="caption grey--text">Setting this branch as Head Office automatically replaces the current Head Office and keeps this branch active.</div></v-col><v-col cols="12" md="6"><v-switch v-model="form.is_active" color="#165134" label="Active"/></v-col></v-row></v-card-text><v-card-actions><v-spacer/><v-btn text :disabled="saving" @click="formDialog=false">Cancel</v-btn><v-btn color="#165134" dark @click="save">Save Branch</v-btn></v-card-actions></v-card></v-dialog><v-dialog v-model="deleteDialog" max-width="520" persistent><v-card><v-card-title>Delete / Deactivate Branch</v-card-title><v-card-text><v-alert type="warning" outlined dense>Branches with active users or projects cannot be removed. Reassign or deactivate those records first. Historical branches are deactivated instead of deleted.</v-alert><strong>{{deleteItem&&deleteItem.name}}</strong></v-card-text><v-card-actions><v-spacer/><v-btn text :disabled="deleting" @click="deleteDialog=false">Cancel</v-btn><v-btn color="error" @click="confirmDelete">Continue</v-btn></v-card-actions></v-card></v-dialog></div></template><script>import api from '../../../services/api';export default{name:'Branches',data:()=>({loading:false,saving:false,deleting:false,dialog:false,formDialog:false,deleteDialog:false,editing:null,deleteItem:null,selected:null,search:'',active:null,items:[],total:0,options:{page:1,itemsPerPage:15},activeOptions:[{text:'Active',value:1},{text:'Inactive',value:0}],form:{name:'',code:'',manager_name:'',phone:'',email:'',city:'',province:'',address:'',latitude:null,longitude:null,is_head_office:false,is_active:true},headers:[{text:'Code',value:'code'},{text:'Branch',value:'name'},{text:'City',value:'city'},{text:'Manager',value:'manager_name'},{text:'Office',value:'is_head_office'},{text:'Status',value:'is_active'},{text:'',value:'actions',sortable:false}]}),watch:{options:{deep:true,handler(){this.load()}}},mounted(){this.load()},methods:{blank(){return{name:'',code:'',manager_name:'',phone:'',email:'',city:'',province:'',address:'',latitude:null,longitude:null,is_head_office:false,is_active:true}},openCreate(){this.editing=null;this.form=this.blank();this.formDialog=true},edit(item){this.editing=item;this.form=Object.assign(this.blank(),item);this.formDialog=true},async save(){if(!this.form.name||!this.form.code){this.$root.$emit('show-error','Branch name and code are required.');return}this.saving=true;try{const r=this.editing?await api.put('/branches/'+this.editing.id,this.form):await api.post('/branches',this.form);this.formDialog=false;await this.load();this.$root.$emit('show-success',r.data.message||'Branch saved successfully.')}catch(e){this.$root.$emit('show-error',(e.response&&e.response.data&&e.response.data.message)||'Unable to save branch.')}finally{this.saving=false}},openDelete(item){this.deleteItem=item;this.deleteDialog=true},async confirmDelete(){if(!this.deleteItem)return;this.deleting=true;try{const r=await api.delete('/branches/'+this.deleteItem.id);this.deleteDialog=false;this.deleteItem=null;await this.load();this.$root.$emit('show-success',r.data.message||'Branch updated successfully.')}catch(e){this.$root.$emit('show-error',(e.response&&e.response.data&&e.response.data.message)||'Unable to delete branch.')}finally{this.deleting=false}},async load(){this.loading=true;try{const params={search:this.search,page:this.options.page,per_page:this.options.itemsPerPage};if(this.active!==null)params.is_active=this.active;const r=await api.get('/branches',{params});this.items=r.data.data||[];this.total=r.data.total||0}catch(e){this.$root.$emit('show-error',(e.response&&e.response.data&&e.response.data.message)||'Unable to load branches.')}finally{this.loading=false}},async view(item){try{const r=await api.get('/branches/'+item.id);this.selected=r.data.data;this.dialog=true}catch(e){this.$root.$emit('show-error','Unable to load branch details.')}}}}</script><style scoped>.page{width:100%}.hero{border-left:4px solid #165134}</style>